# Delete old summary rows for this invoice (handles re-saves)
frappe.db.delete("Item Group Sales Summary", {
    "sales_invoice": doc.name
})

# Group items by item_group
group_totals = {}

for item in doc.items:
    group = item.item_group or "Uncategorized"
    if group not in group_totals:
        group_totals[group] = {"total_qty": 0, "total_amount": 0}
    group_totals[group]["total_qty"]    += flt(item.qty)
    group_totals[group]["total_amount"] += flt(item.amount)

# Insert one summary record per item group
for group_name, values in group_totals.items():
    summary = frappe.get_doc({
        "doctype":       "Item Group Sales Summary",
        "sales_invoice": doc.name,
        "posting_date":  doc.posting_date,
        "customer":      doc.customer,
        "item_group":    group_name,
        "total_qty":     values["total_qty"],
        "total_amount":  values["total_amount"]
    })
    summary.insert(ignore_permissions=True)

frappe.db.commit()
